	// 指定写入文件
	fileHandle, _ := os.Create("./test.log")
  // 同时写入文件和控制台 (只修改这一行)
	writeFile := zapcore.NewMultiWriteSyncer(fileHandle,os.Stdout)
	// 设置日志输出格式为JSON (参数复用NewDevelopmentEncoderConfig)
	encoder := zapcore.NewJSONEncoder(zap.NewDevelopmentEncoderConfig())
