        height: 50,
        width: 50,
      ),
      Spacer(flex: 2), // 弹性系数为2
      Container(
        color: Colors.blue,
        height: 50,
        margin: EdgeInsets.symmetric(horizontal: 5),
        width: 50,
      ),
      Spacer(), // 弹性系数默认为1
      Container(
        color: Colors.blue,
