            cuttStamp += 24 * 3600 * 1000;
        }

        simple = new SimpleAdapter(this, dateList, R.layout.item_grid_date,
                new String[]{"date", "week"}, new int[]{R.id.tv_date, R.id.tv_week});
        gridView.setAdapter(simple);
