        public void askQuestion(final String question){  
            //这里用一个线程就是异步，  
            new Thread(new Runnable() {  
                @Override  
                public void run() {  
                    /** 
                     * 小王调用小李中的方法，在这里注册回调接口 
                     * 这就相当于A类调用B的方法C 
