    public class MyAdapter<T> extends CommonAdapter<T>  
    {  
        public MyAdapter(Context context, List<T> mDatas)  
        {  
            super(context, mDatas);  
        }  

        @Override  
        public View getView(int position, View convertView, ViewGroup parent)  
