    import java.util.Map;  

    import jczb.shoping.adapter.ShoppingCartAdapter;  
    import jczb.shoping.common.AgentApi;  
    import jczb.shoping.model.shoppingCart;  
    import jczb.shoping.ui.SearchActivity.ViewHolder;  
