    XMLRequest xmlRequest = new XMLRequest(  
            "http://flash.weather.com.cn/wmaps/xml/china.xml",  
            new Response.Listener<XmlPullParser>() {  
                @Override  
                public void onResponse(XmlPullParser response) {  
