                    //注册EventBus  
            EventBus.getDefault().register(this);  

            btn = (Button) findViewById(R.id.btn_try);  
            tv = (TextView)findViewById(R.id.tv);  

            btn.setOnClickListener(new View.OnClickListener() {  

                @Override  
                public void onClick(View v) {  
