step 3:编写我们的自定义PagerAdapter适配器类,继承PagerAdapter,实现四个基本的方法:getCount(),isViewFormObject(),instantiateItem(),destoryItem(),同时还要定义一个View的集合,用来放viewpager中的view

MyPagerAdapter.java:
```java
    package com.jay.example.viewpagerdemo1;  

    import java.util.ArrayList;  

    import android.support.v4.view.PagerAdapter;  
    import android.view.View;  
    import android.view.ViewGroup;  

    public class MyPageAdapter extends PagerAdapter {  

        private ArrayList<View> viewLists;      

        public MyPageAdapter() {}     
        public MyPageAdapter(ArrayList<View> viewLists)  
        {  
            super();  
            this.viewLists = viewLists;  
        }  


        @Override  
        public int getCount() {       
            return viewLists.size();  
        }  

        @Override  
        public boolean isViewFromObject(View view, Object object) {  
            return view == object;  
        }  

        @Override  
        public Object instantiateItem(ViewGroup container, int position) {  
            container.addView(viewLists.get(position));  
            return viewLists.get(position);  
        }  

        @Override  
        public void destroyItem(ViewGroup container, int position, Object object) {  
            container.removeView(viewLists.get(position));  
        }  
    }  
```
