                        txtliang.setText("我亮不起来了=-=");  
                        btnclose.setText("亮");  
                    }  
                    else   
                    {  
                        txtliang.setKeepScreenOn(true);  
                        txtliang.setText("我又亮了^-^");  
                        btnclose.setText("不亮");  
