实现代码：

```javascript
    //编写map函数  
    $map = '  
         function() {  
          var key = {to_user:this.to_user,feed_type:this.feed_type};  
          var value = {count:1};  
          emit(key,value);  
        } ';   

    //reduce 函数  
    $reduce = '  
         function(key, values) {  
             var ret = {count:0};  
         for(var i in values) {  
              ret.count += 1;  
          }  
          return ret;  
          }';  

    //查询条件  
    $query = null;  //本实例中没有查询条件，设置为null  
