    class CI_Cache_memcached extends CI_Driver {  

     private $_memcached; // Holds the memcached object  

     protected $_memcache_conf  = array(  
          'default' => array(  
          'default_host'  => '127.0.0.1',  
          'default_port'  => 11211,  
          'default_weight' => 1  
         )  
        );  

