                    if ($thumbWidth == 0) $thumbWidth = 1;  
                    if ($thumbHeight == 0) $thumbHeight = 1;  
                    $createdThumb = imagecreatetruecolor($thumbWidth, $thumbHeight);  
                    if ( !$createdThumb ) {$this->errno = 20; return false;}  
