“redirect_count” //跳转技术  

“total_time” //总耗时

“namelookup_time” //DNS查询耗时

“connect_time” //等待连接耗时

“pretransfer_time” //传输前准备耗时

“size_upload” //上传数据的大小

“size_download” //下载数据的大小

